import unittest
from solution import solve

class Acceptance(unittest.TestCase):
    def test_empty(self): self.assertEqual(solve({}), [])
    def test_chain(self): self.assertEqual(solve({'app':['lib'],'lib':['core']}), ['core','lib','app'])
    def test_lexical(self): self.assertEqual(solve({'z':[],'a':[],'b':[]}), ['a','b','z'])
    def test_available_order(self): self.assertEqual(solve({'b':['a'],'z':[],'a':[]}), ['a','b','z'])
    def test_diamond(self): self.assertEqual(solve({'d':['b','c'],'b':['a'],'c':['a']}), ['a','b','c','d'])
    def test_duplicate(self): self.assertEqual(solve({'b':['a','a']}), ['a','b'])
    def test_cycle(self):
        with self.assertRaises(ValueError): solve({'a':['b'],'b':['a']})
    def test_self(self):
        with self.assertRaises(ValueError): solve({'a':['a']})
    def test_unchanged(self):
        data={'b':['a','a']}; solve(data); self.assertEqual(data, {'b':['a','a']})

if __name__ == "__main__": unittest.main()
